#include "startup.h"
#include <string.h>
void startup_init(struct live_startup *s,void *data,void *key){memset(s,0,sizeof(*s));s->data=data;s->key=key;}
unsigned startup_pending(const struct live_startup *s){return s->head-s->tail;}
int startup_push(struct live_startup *s,const void *p,unsigned n,unsigned flags,uint64_t ms){struct startup_record *q;unsigned first;if(!s||!s->data||!s->key||!p||!n||n>LIVE_AU_LIMIT||flags>31||ms>UINT64_MAX-STARTUP_DELAY_MS)return -1;if(!s->started&&(flags&7)!=7)return -1;if(startup_pending(s)==STARTUP_SLOTS||n>STARTUP_BYTES-s->used){s->overflows++;return -1;}if(s->started&&ms+STARTUP_DELAY_MS<s->last_due)return -1;
 if(!s->started){memcpy(s->key,p,n);s->key_bytes=n;s->key_flags=flags;s->first_ms=s->next_repeat=ms;s->started=1;}
 q=&s->rows[s->head%STARTUP_SLOTS];q->due=s->last_due=ms+STARTUP_DELAY_MS;q->offset=s->write_at;q->bytes=n;q->flags=flags;first=STARTUP_BYTES-s->write_at;if(first>n)first=n;memcpy(s->data+s->write_at,p,first);memcpy(s->data,(const unsigned char*)p+first,n-first);s->write_at=(s->write_at+n)%STARTUP_BYTES;s->used+=n;s->head++;if(s->used>s->peak_bytes)s->peak_bytes=s->used;if(startup_pending(s)>s->peak_frames)s->peak_frames=startup_pending(s);return 0;}
int startup_pop(struct live_startup *s,uint64_t ms,void *out,size_t cap,unsigned *n,unsigned *flags,int *bootstrap){struct startup_record *q;unsigned first;if(!s||!out||!n||!flags||!bootstrap)return -1;if(!s->started)return 0;if(ms<s->first_ms)return -1;
 if(ms-s->first_ms<STARTUP_DELAY_MS){if(s->repeats>=STARTUP_REPEATS||ms<s->next_repeat)return 0;if(cap<s->key_bytes)return -1;memcpy(out,s->key,s->key_bytes);*n=s->key_bytes;*flags=s->key_flags;*bootstrap=1;s->repeats++;s->next_repeat=ms+STARTUP_DELAY_MS/STARTUP_REPEATS;return 1;}
 if(!startup_pending(s)){return 0;}q=&s->rows[s->tail%STARTUP_SLOTS];if(ms<q->due)return 0;if(q->bytes>cap||q->offset!=s->read_at||q->bytes>s->used)return -1;first=STARTUP_BYTES-s->read_at;if(first>q->bytes)first=q->bytes;memcpy(out,s->data+s->read_at,first);memcpy((unsigned char*)out+first,s->data,q->bytes-first);*n=q->bytes;*flags=q->flags;*bootstrap=0;s->read_at=(s->read_at+q->bytes)%STARTUP_BYTES;s->used-=q->bytes;s->tail++;s->emitted++;return 1;}
